+        gap: 0.75rem;
+        padding: 0.9rem 1rem;
+        border: 1px solid var(--surface-border);
+        border-radius: 0.9rem;
+        background: var(--surface);
+        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
+      }
+
+      .choice:hover {
+        border-color: #b8c8e4;
+        transform: translateY(-1px);
