+
+      @media (forced-colors: active) {
+        .card,
+        .form-field,
+        .choice {
+          border-color: ButtonBorder;
+          background: Canvas;
+        }
+
+        body {
+          background: Canvas;
+          color: CanvasText;
+        }
+
+        button {
+          background: ButtonFace;
+          color: ButtonText;
+          border: 1px solid ButtonText;
+        }
+      }
+    </style>
+  </head>
+  <body>
